mapper.sql:
(
    (n.SCOPE_TYPE = 'PRIVATE' AND n.USER_ID = #{userId, jdbcType=NUMERIC})
    OR
    (n.SCOPE_TYPE = 'WS' AND EXISTS (
        SELECT 1 FROM WS_MEMBERS wm
        WHERE wm.WS_ID = n.WS_ID AND wm.USER_ID = #{userId, jdbcType=NUMERIC}
    ))
    OR
    (n.SCOPE_TYPE = 'PROJ' AND EXISTS (
        SELECT 1 FROM PROJ_MEMBERS pm
        WHERE pm.PROJ_ID = n.PROJ_ID AND pm.USER_ID = #{userId, jdbcType=NUMERIC}
    ))
    OR
    EXISTS (
        SELECT 1
        FROM CONTENT_SHARES cs
        WHERE cs.CONTENT_TYPE = 'NOTE'
          AND cs.CONTENT_ID = n.NOTE_ID
          AND cs.ACTIVE_YN = 'Y'

          AND NVL(cs.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
          AND (cs.EXPIRES_AT IS NULL OR cs.EXPIRES_AT >= SYSDATE)
          AND (
              (cs.TARGET_TYPE = 'USER' AND cs.TARGET_ID = #{userId, jdbcType=NUMERIC})
              OR (cs.TARGET_TYPE = 'WS' AND EXISTS (
                  SELECT 1 FROM WS_MEMBERS swm
                  WHERE swm.WS_ID = cs.TARGET_ID AND swm.USER_ID = #{userId, jdbcType=NUMERIC}
              ))
              OR (cs.TARGET_TYPE = 'PROJ' AND EXISTS (
                  SELECT 1 FROM PROJ_MEMBERS spm
                  WHERE spm.PROJ_ID = cs.TARGET_ID AND spm.USER_ID = #{userId, jdbcType=NUMERIC}
              ))
          )
    )
)

(
    (n.SCOPE_TYPE = 'PRIVATE' AND n.USER_ID = #{userId, jdbcType=NUMERIC})
    OR
    (n.SCOPE_TYPE = 'WS' AND EXISTS (
        SELECT 1 FROM WS_MEMBERS wm
        WHERE wm.WS_ID = n.WS_ID AND wm.USER_ID = #{userId, jdbcType=NUMERIC}
    ))
    OR
    (n.SCOPE_TYPE = 'PROJ' AND EXISTS (
        SELECT 1 FROM PROJ_MEMBERS pm
        WHERE pm.PROJ_ID = n.PROJ_ID AND pm.USER_ID = #{userId, jdbcType=NUMERIC}
    ))
)

choose.when:
AND EXISTS (
    SELECT 1
    FROM NOTE_PINS p_important
    WHERE p_important.USER_ID = #{userId, jdbcType=NUMERIC}
      AND p_important.NOTE_ID = n.NOTE_ID
      AND p_important.PIN_SCOPE_KEY = 'NOTE:' || #{userId, jdbcType=NUMERIC}
)

AND n.SCOPE_TYPE = 'PRIVATE' AND n.USER_ID != #{userId, jdbcType=NUMERIC}
AND n.USER_ID = #{friendUserId, jdbcType=NUMERIC}
AND EXISTS ( SELECT 1 FROM CONTENT_SHARES cs_friend_scope WHERE cs_friend_scope.CONTENT_TYPE = 'NOTE' AND cs_friend_scope.CONTENT_ID = n.NOTE_ID AND cs_friend_scope.TARGET_TYPE = 'USER' AND cs_friend_scope.TARGET_ID = #{userId, jdbcType=NUMERIC} AND cs_friend_scope.ACTIVE_YN = 'Y'
AND NVL(cs_friend_scope.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (cs_friend_scope.EXPIRES_AT IS NULL OR cs_friend_scope.EXPIRES_AT >= SYSDATE) )

AND n.SCOPE_TYPE != 'PROJ' AND ( ( n.SCOPE_TYPE = 'WS'
AND n.WS_ID = #{wsId, jdbcType=NUMERIC}
AND EXISTS ( SELECT 1 FROM WS_MEMBERS ws_native_member WHERE ws_native_member.WS_ID = n.WS_ID AND ws_native_member.USER_ID = #{userId, jdbcType=NUMERIC} ) ) OR EXISTS ( SELECT 1 FROM CONTENT_SHARES cs_ws_scope WHERE cs_ws_scope.CONTENT_TYPE = 'NOTE' AND cs_ws_scope.CONTENT_ID = n.NOTE_ID AND cs_ws_scope.TARGET_TYPE = 'WS' AND cs_ws_scope.ACTIVE_YN = 'Y'
AND NVL(cs_ws_scope.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND (cs_ws_scope.EXPIRES_AT IS NULL OR cs_ws_scope.EXPIRES_AT >= SYSDATE)
AND cs_ws_scope.TARGET_ID = #{wsId, jdbcType=NUMERIC}
AND EXISTS ( SELECT 1 FROM WS_MEMBERS ws_shared_member WHERE ws_shared_member.WS_ID = cs_ws_scope.TARGET_ID AND ws_shared_member.USER_ID = #{userId, jdbcType=NUMERIC} ) ) )

AND n.SCOPE_TYPE != 'WS'
AND (
    (
        n.SCOPE_TYPE = 'PROJ'

            AND n.PROJ_ID = #{projId, jdbcType=NUMERIC}


            AND n.WS_ID = #{wsId, jdbcType=NUMERIC}

        AND EXISTS (
            SELECT 1
            FROM PROJ_MEMBERS proj_native_member
            WHERE proj_native_member.PROJ_ID = n.PROJ_ID
              AND proj_native_member.USER_ID = #{userId, jdbcType=NUMERIC}
        )
    )
    OR
    EXISTS (
        SELECT 1
        FROM CONTENT_SHARES cs_proj_scope
        WHERE cs_proj_scope.CONTENT_TYPE = 'NOTE'
          AND cs_proj_scope.CONTENT_ID = n.NOTE_ID
          AND cs_proj_scope.TARGET_TYPE = 'PROJ'
          AND cs_proj_scope.ACTIVE_YN = 'Y'

          AND NVL(cs_proj_scope.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
          AND (cs_proj_scope.EXPIRES_AT IS NULL OR cs_proj_scope.EXPIRES_AT >= SYSDATE)

              AND cs_proj_scope.TARGET_ID = #{projId, jdbcType=NUMERIC}


              AND EXISTS (
                  SELECT 1 FROM PROJECTS selected_ws_project
                  WHERE selected_ws_project.PROJ_ID = cs_proj_scope.TARGET_ID
                    AND selected_ws_project.WS_ID = #{wsId, jdbcType=NUMERIC}
              )

          AND EXISTS (
              SELECT 1
              FROM PROJ_MEMBERS proj_shared_member
              WHERE proj_shared_member.PROJ_ID = cs_proj_scope.TARGET_ID
                AND proj_shared_member.USER_ID = #{userId, jdbcType=NUMERIC}
          )
    )
)

mapper.select:
SELECT * FROM ( SELECT n.NOTE_ID, n.SCOPE_TYPE, n.WS_ID, n.PROJ_ID, n.USER_ID, n.NOTE_TITLE, n.DONE_CONTENT, n.NEXT_CONTENT, n.ISSUE_CONTENT, n.CHANGE_LOG, n.MEMO, n.MOYO_PUBLIC_YN, n.MOYO_PUBLIC_AT, n.CATEGORY, n.ICON, n.FOLDER_ID, nf.FOLDER_NAME, nf.FOLDER_NAME AS FOLDER_PATH, nw.WS_NAME, np.PROJ_NAME, NULL AS SHARE_SCOPE_TYPES, NULL AS SHARE_SCOPE_NAMES, n.REG_DT, n.UPD_DT, n.UPDATED_BY, u.USER_NAME, u.PROFILE_IMAGE_PATH AS PROFILE_IMAGE_PATH, uu.USER_NAME AS UPDATED_BY_NAME, CASE WHEN p.NOTE_ID IS NULL THEN 0 ELSE 1 END AS PINNED, p.PIN_ORDER, CASE WHEN n.USER_ID = #{userId, jdbcType=NUMERIC} THEN 1 WHEN n.SCOPE_TYPE = 'WS' AND (nw.OWNER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(wm_role.WS_ROLE, 'MEMBER')) = 'ADMIN') THEN 1 WHEN n.SCOPE_TYPE = 'PROJ' AND (np.LEADER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(pm_role.PROJ_ROLE, 'MEMBER')) = 'ADMIN') THEN 1 ELSE 0 END AS CAN_MANAGE, CASE WHEN n.USER_ID = #{userId, jdbcType=NUMERIC} THEN 1 WHEN EXISTS ( SELECT 1 FROM CONTENT_SHARES cs_edit_main WHERE cs_edit_main.CONTENT_TYPE = 'NOTE' AND cs_edit_main.CONTENT_ID = n.NOTE_ID AND cs_edit_main.ACTIVE_YN = 'Y'
AND NVL(cs_edit_main.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED' AND cs_edit_main.PERMISSION_TYPE = 'EDIT' AND (cs_edit_main.EXPIRES_AT IS NULL OR cs_edit_main.EXPIRES_AT >= SYSDATE) AND ( (cs_edit_main.TARGET_TYPE = 'USER' AND cs_edit_main.TARGET_ID = #{userId, jdbcType=NUMERIC}) OR (cs_edit_main.TARGET_TYPE = 'WS' AND EXISTS ( SELECT 1 FROM WS_MEMBERS swm_edit_main WHERE swm_edit_main.WS_ID = cs_edit_main.TARGET_ID AND swm_edit_main.USER_ID = #{userId, jdbcType=NUMERIC} )) OR (cs_edit_main.TARGET_TYPE = 'PROJ' AND EXISTS ( SELECT 1 FROM PROJ_MEMBERS spm_edit_main WHERE spm_edit_main.PROJ_ID = cs_edit_main.TARGET_ID AND spm_edit_main.USER_ID = #{userId, jdbcType=NUMERIC} )) ) ) THEN 1 ELSE 0 END AS CAN_EDIT, CASE WHEN n.SCOPE_TYPE = 'PRIVATE' AND n.USER_ID = #{userId, jdbcType=NUMERIC} THEN 1 WHEN n.SCOPE_TYPE = 'WS' AND (nw.OWNER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(wm_role.WS_ROLE, 'MEMBER')) = 'ADMIN') THEN 1 WHEN n.SCOPE_TYPE = 'PROJ' AND (np.LEADER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(pm_role.PROJ_ROLE, 'MEMBER')) = 'ADMIN') THEN 1 ELSE 0 END AS CAN_MANAGE_SPACE FROM NOTES n JOIN USERS u ON n.USER_ID = u.USER_ID LEFT JOIN USERS uu ON uu.USER_ID = n.UPDATED_BY LEFT JOIN NOTE_FOLDERS nf ON nf.FOLDER_ID = n.FOLDER_ID LEFT JOIN WORKSPACES nw ON nw.WS_ID = n.WS_ID LEFT JOIN PROJECTS np ON np.PROJ_ID = n.PROJ_ID LEFT JOIN WS_MEMBERS wm_role ON wm_role.WS_ID = n.WS_ID AND wm_role.USER_ID = #{userId, jdbcType=NUMERIC} LEFT JOIN PROJ_MEMBERS pm_role ON pm_role.PROJ_ID = n.PROJ_ID AND pm_role.USER_ID = #{userId, jdbcType=NUMERIC} LEFT JOIN ( SELECT USER_ID, NOTE_ID, MIN(PIN_ORDER) AS PIN_ORDER FROM NOTE_PINS WHERE USER_ID = #{userId, jdbcType=NUMERIC} AND PIN_SCOPE_KEY = 'NOTE:' || #{userId, jdbcType=NUMERIC} GROUP BY USER_ID, NOTE_ID ) p ON p.NOTE_ID = n.NOTE_ID AND p.USER_ID = #{userId, jdbcType=NUMERIC} WHERE AND NVL(n.DELETED_YN, 'N') = 'N'
AND ( p.NOTE_ID IS NOT NULL OR NOT EXISTS ( SELECT 1 FROM NOTE_PINS px WHERE px.USER_ID = #{userId, jdbcType=NUMERIC} AND px.PIN_SCOPE_KEY = 'NOTE:' || #{userId, jdbcType=NUMERIC} ) ) ORDER BY CASE WHEN p.NOTE_ID IS NULL THEN 1 ELSE 0 END, p.PIN_ORDER ASC, n.REG_DT DESC, n.NOTE_ID DESC ) WHERE ROWNUM <= #{limit, jdbcType=NUMERIC}

SELECT COUNT(*)
FROM NOTE_PINS
WHERE USER_ID = #{userId, jdbcType=NUMERIC}
  AND PIN_SCOPE_KEY = 'NOTE:' || #{userId, jdbcType=NUMERIC}

SELECT NVL(MAX(PIN_ORDER), 0) + 1
FROM NOTE_PINS
WHERE USER_ID = #{userId, jdbcType=NUMERIC}
  AND PIN_SCOPE_KEY = #{pinScopeKey, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM NOTE_PINS
WHERE USER_ID = #{userId, jdbcType=NUMERIC}
  AND NOTE_ID = #{noteId, jdbcType=NUMERIC}

mapper.select:
SELECT COUNT(*)
FROM NOTES n
LEFT JOIN WORKSPACES w ON w.WS_ID = n.WS_ID
LEFT JOIN WS_MEMBERS wm ON wm.WS_ID = n.WS_ID AND wm.USER_ID = #{userId, jdbcType=NUMERIC}
LEFT JOIN PROJECTS p ON p.PROJ_ID = n.PROJ_ID
LEFT JOIN PROJ_MEMBERS pm ON pm.PROJ_ID = n.PROJ_ID AND pm.USER_ID = #{userId, jdbcType=NUMERIC}
WHERE n.NOTE_ID = #{noteId, jdbcType=NUMERIC}
  AND (
        n.USER_ID = #{userId, jdbcType=NUMERIC}
        OR (n.SCOPE_TYPE = 'WS' AND (w.OWNER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(wm.WS_ROLE, 'MEMBER')) = 'ADMIN'))
        OR (n.SCOPE_TYPE = 'PROJ' AND (p.LEADER_ID = #{userId, jdbcType=NUMERIC} OR UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) = 'ADMIN'))
      )

SELECT COUNT(*) FROM NOTES
 WHERE NOTE_ID = #{noteId}
   AND NVL(DELETED_YN, 'N') = 'Y'
   AND DELETED_BY = #{userId}

SELECT FILE_ID, NOTE_ID, ORIGIN_FILE_NAME, STORED_FILE_NAME, FILE_PATH, FILE_SIZE, FILE_EXT, REG_DT
FROM NOTE_FILES
WHERE FILE_ID = #{fileId, jdbcType=NUMERIC}

SELECT NVL(VIEW_COUNT, 0)
  FROM NOTES
 WHERE NOTE_ID = #{noteId, jdbcType=NUMERIC}

SELECT COUNT(*)
  FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'NOTE'
   AND CONTENT_ID = #{noteId, jdbcType=NUMERIC}
   AND USER_ID = #{userId, jdbcType=NUMERIC}
   AND REACTION_TYPE = 'LIKE'

