mapper.update:
UPDATE NOTE_REPLIES
SET REPLY_CONTENT = #{replyContent, jdbcType=CLOB},
    UPD_DT = SYSDATE
WHERE REPLY_ID = #{replyId, jdbcType=NUMERIC}
  AND NOTE_ID = #{noteId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM CONTENT_REACTIONS
 WHERE CONTENT_TYPE = 'NOTE_REPLY'
   AND REACTION_TYPE = 'LIKE'
   AND CONTENT_ID IN (
        SELECT R.REPLY_ID
          FROM NOTE_REPLIES R
         WHERE (R.REPLY_ID = #{replyId, jdbcType=NUMERIC}
                OR R.PARENT_REPLY_ID = #{replyId, jdbcType=NUMERIC})
           AND EXISTS (
                SELECT 1
                  FROM NOTE_REPLIES OWNER_REPLY
                 WHERE OWNER_REPLY.REPLY_ID = #{replyId, jdbcType=NUMERIC}
                   AND OWNER_REPLY.USER_ID = #{userId, jdbcType=NUMERIC}
           )
   )

DELETE FROM NOTE_REPLIES
WHERE REPLY_ID = #{replyId, jdbcType=NUMERIC}
  AND USER_ID = #{userId, jdbcType=NUMERIC}
